local encoded = ""

local function decode(str)
    local b = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local decoded = {}
    for i = 1, #str, 4 do
        local c1 = b:find(str:sub(i, i)) - 1
        local c2 = b:find(str:sub(i+1, i+1)) - 1
        local c3 = b:find(str:sub(i+2, i+2)) - 1
        local c4 = b:find(str:sub(i+3, i+3)) - 1
        local n = (c1 << 18) | (c2 << 12) | (c3 << 6) | c4
        table.insert(decoded, string.char((n >> 16) & 0xFF))
        table.insert(decoded, string.char((n >> 8) & 0xFF))
        table.insert(decoded, string.char(n & 0xFF))
    end
    return table.concat(decoded)
end

loadstring(decode(encoded))()
